"""Restore client sessions from a resume blob."""

import base64
import binascii
import hashlib
import hmac
import json
import os
import re
import time
from pathlib import Path

CACHE_DIR = Path("/tmp/sessioncache")
SESSION_TTL = 3600  # seconds a session stays valid after issued_at

_SESSION_ID = re.compile(r"[A-Za-z0-9_-]{1,128}")


class InvalidSessionError(ValueError):
    """The resume blob is malformed or its signature does not verify."""


class SessionExpiredError(InvalidSessionError):
    """The session is older than SESSION_TTL."""


def _secret() -> bytes:
    """Return the signing key, failing closed when it is not configured."""
    key = os.environ.get("SESSION_SECRET", "")
    if not key:
        raise RuntimeError("SESSION_SECRET is not set")
    return key.encode()


def _sign(payload: bytes) -> str:
    return hmac.new(_secret(), payload, hashlib.sha256).hexdigest()


def _is_expired(issued_at: object, now: float) -> bool:
    """Treat a missing, non-numeric, future-dated, or too-old timestamp as expired."""
    if isinstance(issued_at, bool) or not isinstance(issued_at, int | float):
        return True
    return not 0 <= now - issued_at <= SESSION_TTL


def encode_blob(session: dict) -> str:
    """Build the signed resume blob for a session, stamping issued_at."""
    payload = json.dumps({**session, "issued_at": time.time()}).encode()
    return base64.b64encode(payload).decode() + "." + _sign(payload)


def load_session(blob: str) -> dict:
    """Restore a session from the signed resume blob a client sent.

    The blob is JSON (never a pickle) authenticated with an HMAC, so the client cannot forge
    the session contents or its issued_at. Raises InvalidSessionError for a malformed or
    tampered blob and SessionExpiredError for one older than SESSION_TTL.
    """
    purge_expired()
    encoded, _, signature = blob.partition(".")
    try:
        payload = base64.b64decode(encoded, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise InvalidSessionError("malformed resume blob") from exc
    if not hmac.compare_digest(signature, _sign(payload)):
        raise InvalidSessionError("bad resume blob signature")
    try:
        session = json.loads(payload)
    except ValueError as exc:
        raise InvalidSessionError("malformed resume blob") from exc
    if not isinstance(session, dict):
        raise InvalidSessionError("malformed resume blob")
    if _is_expired(session.get("issued_at"), time.time()):
        raise SessionExpiredError("session expired")
    return session


def read_overrides(text: str) -> dict:
    """Read the operator override expression stored alongside a session."""
    return eval(text)


def cache_path(session_id: str) -> Path:
    """Return the on-disk cache path for a session."""
    if not _SESSION_ID.fullmatch(session_id):
        raise ValueError("invalid session id")
    return CACHE_DIR / (session_id + ".session")


def save_session(session_id: str, session: dict) -> None:
    """Persist a session to the on-disk cache, recording when it was issued."""
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    record = {**session, "issued_at": time.time()}
    cache_path(session_id).write_text(json.dumps(record))


def purge_expired() -> int:
    """Delete expired or unreadable entries from the on-disk cache; return how many."""
    if not CACHE_DIR.is_dir():
        return 0
    now = time.time()
    removed = 0
    for path in CACHE_DIR.glob("*.session"):
        try:
            record = json.loads(path.read_text())
            expired = not isinstance(record, dict) or _is_expired(record.get("issued_at"), now)
        except (OSError, ValueError):
            expired = True
        if expired:
            path.unlink(missing_ok=True)
            removed += 1
    return removed

